import {
	getOperatorArity,
	isSearchColumn,
	useDataExplorerContext,
	useInlineFilterFlow,
} from "@adistack/data-explorer";
import { IconFilterX, IconSearch } from "@tabler/icons-react";
import { useCallback, useEffect, useState } from "react";

import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { ColumnSelector } from "./column-selector.tsx";
import { FilterChipGroup } from "./filter-chip-group.tsx";
import { OperatorSelector } from "./operator-selector.tsx";
import { useFilterBarKeyboard } from "./use-filter-bar-keyboard.ts";
import { ValueInput } from "./value-input.tsx";

interface FilterBarProps {
	className?: string;
}

export function FilterBar({ className }: FilterBarProps): React.JSX.Element {
	const { columnsConfig, table } = useDataExplorerContext();
	const filterConditions = table.state.dataFilters;
	const {
		addDataFilter,
		clearDataFilters,
		removeDataFilter,
		updateDataFilter,
	} = table;

	const [popoverOpen, setPopoverOpen] = useState(false);

	const { state: flow, actions } = useInlineFilterFlow({
		columnsConfig,
		onAdd: addDataFilter,
	});

	useEffect(() => {
		if (flow.phase === "column") setPopoverOpen(true);
		if (flow.phase === "idle") setPopoverOpen(false);
	}, [flow.phase]);

	const keyboard = useFilterBarKeyboard({
		conditions: filterConditions,
		inputValue: flow.inputValue,
		onRemove: removeDataFilter,
		onResetFlow: () => {
			actions.reset();
			setPopoverOpen(false);
		},
		popoverOpen,
	});
	const {
		containerRef,
		focusedChipIndex,
		setFocusedChipIndex,
		focusInput,
		handleInputKeyDown,
		inputRef,
	} = keyboard;

	const closeAndFocus = useCallback(() => {
		setPopoverOpen(false);
		focusInput();
	}, [focusInput]);

	const commitCondition = useCallback(() => {
		actions.commit();
		closeAndFocus();
	}, [actions, closeAndFocus]);

	const handleClearAll = useCallback(
		(e: React.MouseEvent) => {
			e.stopPropagation();
			clearDataFilters();
			setFocusedChipIndex(null);
			focusInput();
		},
		[clearDataFilters, setFocusedChipIndex, focusInput],
	);

	const handleContainerClick = useCallback(
		(e: React.MouseEvent) => {
			if (e.target === e.currentTarget) {
				focusInput();
				setFocusedChipIndex(null);
			}
		},
		[focusInput, setFocusedChipIndex],
	);

	const handleCombinatorChange = useCallback(
		(id: string, combinator: "and" | "or") => {
			updateDataFilter(id, { combinator });
		},
		[updateDataFilter],
	);

	return (
		<div className={className}>
			<div
				aria-expanded={popoverOpen}
				aria-label="Filter conditions"
				className={cn(
					"flex h-9 w-full min-w-0 items-center gap-1 rounded-lg border border-input bg-transparent px-2.5 py-1 text-sm shadow-xs transition-colors",
					"focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50",
					"placeholder:text-muted-foreground",
				)}
				data-slot="filter-bar"
				onClick={handleContainerClick}
				onKeyDown={(e) => {
					if (e.key === "Enter" || e.key === " ") {
						e.preventDefault();
						inputRef.current?.focus();
					}
				}}
				ref={containerRef}
				role="combobox"
				tabIndex={-1}
			>
				<IconSearch className="size-4 shrink-0 text-muted-foreground" />

				<FilterChipGroup
					columnsConfig={columnsConfig}
					conditions={filterConditions}
					focusedChipIndex={focusedChipIndex}
					handleCombinatorChange={handleCombinatorChange}
					removeCondition={removeDataFilter}
					setFocusedChipIndex={setFocusedChipIndex}
					updateCondition={updateDataFilter}
				/>

				<input
					aria-label="Filter input"
					className="min-w-0 grow bg-transparent text-sm outline-none placeholder:text-muted-foreground"
					onChange={(e) => actions.handleInputChange(e.target.value)}
					onFocus={() => setFocusedChipIndex(null)}
					onKeyDown={handleInputKeyDown}
					placeholder={
						filterConditions.length > 0 ? "Filter..." : "Filter (Ctrl+F)"
					}
					ref={inputRef}
					value={flow.inputValue}
				/>

				{filterConditions.length > 0 && (
					<button
						aria-label="Clear all filters"
						className="shrink-0 text-muted-foreground transition-colors hover:text-foreground"
						onClick={handleClearAll}
						type="button"
					>
						<IconFilterX className="size-4" />
					</button>
				)}
			</div>

			<Popover
				onOpenChange={(open) => {
					setPopoverOpen(open);
					if (!open) actions.reset();
				}}
				open={popoverOpen}
			>
				<PopoverTrigger className="sr-only" tabIndex={-1} />
				<PopoverContent align="start" className="w-80 p-0" side="bottom">
					<FilterPopoverContent
						actions={actions}
						columnsConfig={columnsConfig}
						flow={flow}
						onCloseAndFocus={closeAndFocus}
						onCommit={commitCondition}
					/>
				</PopoverContent>
			</Popover>
		</div>
	);
}

interface FilterPopoverContentProps {
	actions: ReturnType<typeof useInlineFilterFlow>["actions"];
	columnsConfig: ReturnType<typeof useDataExplorerContext>["columnsConfig"];
	flow: ReturnType<typeof useInlineFilterFlow>["state"];
	onCloseAndFocus: () => void;
	onCommit: () => void;
}

function FilterPopoverContent({
	flow,
	actions,
	columnsConfig,
	onCloseAndFocus,
	onCommit,
}: FilterPopoverContentProps): React.JSX.Element | null {
	if (flow.phase === "column") {
		return (
			<ColumnSelector
				columns={columnsConfig}
				onQuickValueSelect={(colId, val) => {
					actions.handleQuickValueSelect(colId, val);
					onCloseAndFocus();
				}}
				onSearchChange={actions.setSearchText}
				onSelect={(colId) => {
					actions.handleColumnSelect(colId);
					if (isSearchColumn(colId)) onCloseAndFocus();
				}}
				search={flow.searchText}
			/>
		);
	}

	if (flow.phase === "operator" && flow.selectedColumn) {
		return (
			<OperatorSelector
				column={flow.selectedColumn}
				onSearchChange={actions.setSearchText}
				onSelect={(op) => {
					actions.handleOperatorSelect(op);
					if (getOperatorArity(op) === "nullary") {
						onCloseAndFocus();
					}
				}}
				search={flow.searchText}
			/>
		);
	}

	if (
		flow.phase === "value" &&
		flow.selectedColumn &&
		flow.selectedOperator &&
		!flow.needsNullValue
	) {
		const isGlobalSearch =
			flow.selectedOperator === "contains" &&
			flow.selectedColumnId !== null &&
			isSearchColumn(flow.selectedColumnId);
		return (
			<div className="p-2">
				<div className="mb-2 text-muted-foreground text-xs">
					{flow.selectedColumn.displayName}{" "}
					{isGlobalSearch ? "contains" : "— enter value"}
				</div>
				<ValueInput
					column={flow.selectedColumn}
					onChange={actions.setPendingValue}
					onCommit={onCommit}
					operator={flow.selectedOperator}
					value={flow.pendingValue}
				/>
				{flow.error !== null && (
					<p className="mt-1 text-destructive text-xs" role="alert">
						{flow.error}
					</p>
				)}
				<div className="mt-2 flex justify-end">
					<button
						className="rounded-md bg-primary px-3 py-1 text-primary-foreground text-xs"
						onClick={onCommit}
						type="button"
					>
						Apply
					</button>
				</div>
			</div>
		);
	}

	return null;
}

import type { ColumnConfig } from "@adistack/data-explorer";
import { isSearchColumn } from "@adistack/data-explorer";
import { useMemo } from "react";

import {
	Command,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandItem,
	CommandList,
} from "@/components/ui/command";

interface ColumnSelectorProps {
	columns: ColumnConfig[];
	onQuickValueSelect?: (columnId: string, value: string) => void;
	onSearchChange: (value: string) => void;
	onSelect: (columnId: string) => void;
	search: string;
}

export function ColumnSelector({
	columns,
	search,
	onSearchChange,
	onSelect,
	onQuickValueSelect,
}: ColumnSelectorProps): React.JSX.Element {
	const term = search.trim().toLowerCase();
	const filteredColumns = useMemo(() => {
		if (!term) return columns;
		return columns.filter(
			(c) =>
				c.displayName.toLowerCase().includes(term) ||
				c.id.toLowerCase().includes(term),
		);
	}, [columns, term]);

	const quickMatches = useMemo(() => {
		if (term.length < 2) return [];
		const matches: {
			columnId: string;
			columnDisplayName: string;
			option: { label: string; value: string };
		}[] = [];

		for (const col of columns) {
			if (col.type !== "enum" && col.type !== "multiEnum") continue;
			const opts = col.options ?? [];
			for (const opt of opts) {
				if (
					opt.label.toLowerCase().includes(term) ||
					opt.value.toLowerCase().includes(term)
				) {
					matches.push({
						columnDisplayName: col.displayName,
						columnId: col.id,
						option: opt,
					});
				}
			}
		}
		return matches;
	}, [term, columns]);

	return (
		<Command
			filter={(value, query) =>
				value.toLowerCase().includes(query.toLowerCase()) ? 1 : 0
			}
			loop={true}
		>
			<CommandInput
				onValueChange={onSearchChange}
				placeholder="Filter columns..."
				value={search}
			/>
			<CommandEmpty>No columns found</CommandEmpty>
			<CommandList className="max-h-64">
				<CommandGroup heading="Columns">
					{filteredColumns.map((col) => {
						const Icon = col.icon as
							| React.ComponentType<{
									className?: string;
									strokeWidth?: number;
							  }>
							| undefined;
						return (
							<CommandItem
								key={col.id}
								keywords={[col.displayName]}
								onSelect={() => onSelect(col.id)}
								value={col.id}
							>
								<div className="flex w-full items-center gap-1.5">
									{!!Icon && (
										<Icon className="size-4 shrink-0" strokeWidth={2.25} />
									)}
									<span>{col.displayName}</span>
									{isSearchColumn(col) && (
										<span className="ml-auto text-muted-foreground text-xs">
											Search all
										</span>
									)}
								</div>
							</CommandItem>
						);
					})}
				</CommandGroup>
				{quickMatches.length > 0 && (
					<CommandGroup heading="Quick values">
						{quickMatches.map((m) => (
							<CommandItem
								key={`${m.columnId}-${m.option.value}`}
								keywords={[m.option.label, m.columnDisplayName]}
								onSelect={() =>
									onQuickValueSelect?.(m.columnId, m.option.value)
								}
								value={`${m.columnId}-${m.option.value}`}
							>
								<div className="flex items-center gap-1.5">
									<span className="text-muted-foreground">
										{m.columnDisplayName}
									</span>
									<span className="text-muted-foreground/75">&rarr;</span>
									<span>{m.option.label}</span>
								</div>
							</CommandItem>
						))}
					</CommandGroup>
				)}
			</CommandList>
		</Command>
	);
}

import type { ColumnConfig, FilterOperator } from "@adistack/data-explorer";
import { getOperatorLabel, getOperatorsForType } from "@adistack/data-explorer";

import {
	Command,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandItem,
	CommandList,
} from "@/components/ui/command";

interface OperatorSelectorProps {
	column: ColumnConfig;
	onSearchChange: (value: string) => void;
	onSelect: (operator: FilterOperator) => void;
	search: string;
}

export function OperatorSelector({
	column,
	onSelect,
	search,
	onSearchChange,
}: OperatorSelectorProps): React.JSX.Element {
	const operators = column.operators ?? getOperatorsForType(column.type);

	const filteredOperators = operators.filter((op) => {
		if (!search.trim()) return true;
		const label = getOperatorLabel(op);
		return label.toLowerCase().includes(search.toLowerCase());
	});

	return (
		<Command loop={true}>
			<CommandInput
				onValueChange={onSearchChange}
				placeholder="Select operator..."
				value={search}
			/>
			<CommandEmpty>No operator found</CommandEmpty>
			<CommandList className="max-h-48">
				<CommandGroup>
					{filteredOperators.map((op) => (
						<CommandItem key={op} onSelect={() => onSelect(op)} value={op}>
							<span>{getOperatorLabel(op)}</span>
						</CommandItem>
					))}
				</CommandGroup>
			</CommandList>
		</Command>
	);
}

import type { ColumnConfig, FilterOperator } from "@adistack/data-explorer";
import { editorKind } from "@adistack/data-explorer";
import { IconChevronDown } from "@tabler/icons-react";
import { useState } from "react";

import { Calendar } from "@/components/ui/calendar";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { Switch } from "@/components/ui/switch";
import { toValidDate } from "@/lib/dates";

export { parseDateValue, toValidDate } from "@/lib/dates";

interface ValueInputProps {
	column: ColumnConfig;
	onChange: (value: unknown) => void;
	onCommit: () => void;
	operator: FilterOperator;
	value: unknown;
}

function toNumberOrUndefined(raw: string): number | undefined {
	if (raw === "") return undefined;
	const n = Number(raw);
	return Number.isNaN(n) ? undefined : n;
}

export function ValueInput({
	column,
	operator,
	value,
	onChange,
	onCommit,
}: ValueInputProps): React.JSX.Element | null {
	const kind = editorKind(operator, column);

	if (kind === "nullary") {
		return null;
	}

	if (kind === "search") {
		return (
			<StringInput
				onChange={onChange}
				onCommit={onCommit}
				placeholder="Search..."
				value={typeof value === "string" ? value : undefined}
			/>
		);
	}

	if (kind === "multi") {
		return (
			<MultiOptionInput
				column={column}
				onChange={onChange}
				onCommit={onCommit}
				value={value}
			/>
		);
	}

	switch (column.type) {
		case "string":
			return (
				<StringInput
					onChange={onChange}
					onCommit={onCommit}
					placeholder="Value..."
					value={typeof value === "string" ? value : undefined}
				/>
			);
		case "number":
			if (operator === "between" || operator === "notBetween") {
				return (
					<NumberRangeInput
						onChange={onChange}
						value={
							Array.isArray(value) ? (value as [number, number]) : undefined
						}
					/>
				);
			}
			return (
				<NumberInput
					onChange={onChange}
					onCommit={onCommit}
					value={typeof value === "number" ? value : undefined}
				/>
			);
		case "date":
			if (operator === "between" || operator === "notBetween") {
				return (
					<DateRangeInput
						onChange={onChange}
						value={
							Array.isArray(value) ? (value as [string, string]) : undefined
						}
					/>
				);
			}
			return (
				<DateInput
					onChange={onChange}
					value={typeof value === "string" ? value : undefined}
				/>
			);
		case "boolean":
			return (
				<BooleanInput
					onChange={onChange}
					value={typeof value === "boolean" ? value : undefined}
				/>
			);
		case "enum":
			return (
				<SingleOptionInput
					column={column}
					onChange={onChange}
					onCommit={onCommit}
					value={typeof value === "string" ? value : undefined}
				/>
			);
		case "multiEnum":
			return (
				<MultiOptionInput
					column={column}
					onChange={onChange}
					onCommit={onCommit}
					value={value}
				/>
			);
		default:
			throw new Error(`Unhandled column type: ${String(column.type)}`);
	}
}

interface StringInputProps {
	onChange: (v: unknown) => void;
	onCommit: () => void;
	placeholder: string;
	value: string | undefined;
}

interface NumberInputProps {
	onChange: (v: unknown) => void;
	onCommit: () => void;
	value: number | undefined;
}

interface NumberRangeInputProps {
	onChange: (v: unknown) => void;
	value: [number, number] | undefined;
}

interface DateInputProps {
	onChange: (v: unknown) => void;
	value: string | undefined;
}

interface DateRangeInputProps {
	onChange: (v: unknown) => void;
	value: [string, string] | undefined;
}

interface BooleanInputProps {
	onChange: (v: unknown) => void;
	value: boolean | undefined;
}

interface SingleOptionInputProps {
	column: ColumnConfig;
	onChange: (v: unknown) => void;
	onCommit: () => void;
	value: string | undefined;
}

interface MultiOptionInputProps {
	column: ColumnConfig;
	onChange: (v: unknown) => void;
	onCommit: () => void;
	value: unknown;
}

function StringInput({
	value,
	onChange,
	onCommit,
	placeholder,
}: StringInputProps): React.JSX.Element {
	return (
		<Input
			autoFocus={true}
			className="h-8 text-sm"
			onChange={(e) => onChange(e.target.value)}
			onKeyDown={(e) => {
				if (e.key === "Enter") onCommit();
			}}
			placeholder={placeholder}
			value={value ?? ""}
		/>
	);
}

function NumberInput({
	value,
	onChange,
	onCommit,
}: NumberInputProps): React.JSX.Element {
	return (
		<Input
			autoFocus={true}
			className="h-8 text-sm"
			onChange={(e) => {
				onChange(toNumberOrUndefined(e.target.value));
			}}
			onKeyDown={(e) => {
				if (e.key === "Enter") onCommit();
			}}
			placeholder="Number..."
			type="number"
			value={value ?? ""}
		/>
	);
}

function NumberRangeInput({
	value,
	onChange,
}: NumberRangeInputProps): React.JSX.Element {
	const [min, max] = value ?? [undefined, undefined];
	return (
		<div className="flex items-center gap-1">
			<Input
				autoFocus={true}
				className="h-8 text-sm"
				onChange={(e) => {
					onChange([toNumberOrUndefined(e.target.value), max]);
				}}
				placeholder="Min"
				type="number"
				value={min ?? ""}
			/>
			<span className="text-muted-foreground text-xs">and</span>
			<Input
				className="h-8 text-sm"
				onChange={(e) => {
					onChange([min, toNumberOrUndefined(e.target.value)]);
				}}
				placeholder="Max"
				type="number"
				value={max ?? ""}
			/>
		</div>
	);
}

function DateInput({ value, onChange }: DateInputProps): React.JSX.Element {
	const [open, setOpen] = useState(false);
	const dateValue = toValidDate(value);

	return (
		<Popover onOpenChange={setOpen} open={open}>
			<PopoverTrigger asChild={true}>
				<button
					className="inline-flex h-8 items-center gap-1.5 rounded-md border px-2 text-sm"
					type="button"
				>
					<span className={value ? "" : "text-muted-foreground"}>
						{value ?? "Pick a date..."}
					</span>
					<IconChevronDown className="size-3.5 text-muted-foreground" />
				</button>
			</PopoverTrigger>
			<PopoverContent align="start" className="w-auto p-0">
				<Calendar
					mode="single"
					onSelect={(d) => {
						if (d) {
							onChange(d.toISOString().split("T")[0]);
						}
						setOpen(false);
					}}
					selected={dateValue}
				/>
			</PopoverContent>
		</Popover>
	);
}

function DateRangeInput({
	value,
	onChange,
}: DateRangeInputProps): React.JSX.Element {
	const [open, setOpen] = useState(false);
	const [from, to] = value ?? [undefined, undefined];
	const fromValue = toValidDate(from);
	const toValue = toValidDate(to);

	return (
		<Popover onOpenChange={setOpen} open={open}>
			<PopoverTrigger asChild={true}>
				<button
					className="inline-flex h-8 items-center gap-1.5 rounded-md border px-2 text-sm"
					type="button"
				>
					<span className={from ? "" : "text-muted-foreground"}>
						{from ?? "From..."}
					</span>
					<span className="text-muted-foreground">–</span>
					<span className={to ? "" : "text-muted-foreground"}>
						{to ?? "To..."}
					</span>
					<IconChevronDown className="size-3.5 text-muted-foreground" />
				</button>
			</PopoverTrigger>
			<PopoverContent align="start" className="w-auto p-0">
				<Calendar
					mode="range"
					onSelect={(range) => {
						const f = range?.from
							? range.from.toISOString().split("T")[0]
							: undefined;
						const t = range?.to
							? range.to.toISOString().split("T")[0]
							: undefined;
						if (f && t) {
							onChange([f, t]);
							setOpen(false);
						} else {
							onChange([f ?? "", t ?? ""]);
						}
					}}
					selected={
						fromValue && toValue ? { from: fromValue, to: toValue } : undefined
					}
				/>
			</PopoverContent>
		</Popover>
	);
}

function BooleanInput({
	value,
	onChange,
}: BooleanInputProps): React.JSX.Element {
	return (
		<div className="flex items-center gap-2">
			<Switch
				checked={value ?? false}
				onCheckedChange={(checked) => onChange(checked)}
			/>
			<span className="text-sm">
				{value === undefined ? "Select value..." : value ? "Yes" : "No"}
			</span>
		</div>
	);
}

function SingleOptionInput({
	column,
	value,
	onChange,
	onCommit,
}: SingleOptionInputProps): React.JSX.Element {
	const options = column.options ?? [];
	if (options.length === 0) {
		return (
			<StringInput
				onChange={onChange}
				onCommit={onCommit}
				placeholder="Value..."
				value={value}
			/>
		);
	}
	return (
		<div className="flex flex-col gap-1">
			{options.map((opt) => (
				<button
					className={
						value === opt.value
							? "rounded-md bg-muted px-2 py-1 text-left text-sm font-medium"
							: "rounded-md px-2 py-1 text-left text-sm hover:bg-muted/50"
					}
					key={opt.value}
					onClick={() => onChange(opt.value)}
					type="button"
				>
					{opt.label}
				</button>
			))}
		</div>
	);
}

function MultiOptionInput({
	column,
	value,
	onChange,
	onCommit,
}: MultiOptionInputProps): React.JSX.Element {
	const options = column.options ?? [];
	const selected = new Set(Array.isArray(value) ? value.map(String) : []);

	const toggle = (optValue: string): void => {
		const next = new Set(selected);
		if (next.has(optValue)) next.delete(optValue);
		else next.add(optValue);
		onChange([...next]);
	};

	if (options.length === 0) {
		return (
			<StringInput
				onChange={(v) => {
					const str = String(v ?? "");
					onChange(
						str === ""
							? []
							: str.split(",").flatMap((s) => {
									const trimmed = s.trim();
									return trimmed ? [trimmed] : [];
								}),
					);
				}}
				onCommit={onCommit}
				placeholder="a, b, c..."
				value={Array.isArray(value) ? value.join(", ") : undefined}
			/>
		);
	}

	return (
		<div className="flex flex-col gap-1">
			{options.map((opt) => (
				<button
					className="flex cursor-pointer items-center gap-2 rounded-md px-2 py-1 text-left text-sm hover:bg-muted/50"
					key={opt.value}
					onClick={() => toggle(opt.value)}
					type="button"
				>
					<Checkbox
						checked={selected.has(opt.value)}
						onCheckedChange={() => toggle(opt.value)}
						tabIndex={-1}
					/>
					<span>{opt.label}</span>
				</button>
			))}
		</div>
	);
}

import type {
	ColumnConfig,
	FilterCondition,
	FilterOperator,
} from "@adistack/data-explorer";
import {
	coerceFilterValue,
	formatFilterValue,
	getOperatorLabel,
} from "@adistack/data-explorer";
import { IconX } from "@tabler/icons-react";
import { useState } from "react";

import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { OperatorSelector } from "./operator-selector.tsx";
import { ValueInput } from "./value-input.tsx";

interface FilterChipProps {
	column: ColumnConfig;
	condition: FilterCondition;
	onRemove: (id: string) => void;
	onSelect: () => void;
	onUpdate: (id: string, updates: Partial<FilterCondition>) => void;
	selected: boolean;
}

export function FilterChip({
	condition,
	column,
	onUpdate,
	onRemove,
	selected,
	onSelect,
}: FilterChipProps): React.JSX.Element {
	const [editOpen, setEditOpen] = useState(false);
	const Icon = column.icon as
		| React.ComponentType<{ className?: string; strokeWidth?: number }>
		| undefined;
	const operatorLabel = getOperatorLabel(condition.operator);

	const handleRemove = (e: React.MouseEvent | React.KeyboardEvent): void => {
		e.stopPropagation();
		onRemove(condition.id);
	};

	const handleOperatorChange = (operator: FilterOperator): void => {
		const { value } = coerceFilterValue(operator, condition.value);
		onUpdate(condition.id, { operator, value });
	};

	const displayValue = formatFilterValue(
		condition.value,
		condition.operator,
		column,
	);

	return (
		<Popover onOpenChange={setEditOpen} open={editOpen}>
			<PopoverTrigger asChild={true}>
				<span
					className={cn(
						"inline-flex h-7 items-center gap-1 rounded-md border px-1.5 text-xs transition-colors",
						selected
							? "border-ring bg-muted"
							: "border-border bg-background hover:bg-muted/50",
					)}
					data-filter-chip={condition.id}
				>
					<button
						className="flex min-w-0 cursor-pointer items-center gap-1 bg-transparent"
						onClick={onSelect}
						type="button"
					>
						{!!Icon && (
							<Icon
								className="size-3.5 shrink-0 text-muted-foreground"
								strokeWidth={2.25}
							/>
						)}
						<span className="font-medium">{column.displayName}</span>
						<span className="text-muted-foreground">{operatorLabel}</span>
						{displayValue !== null && (
							<span className="max-w-24 truncate">{displayValue}</span>
						)}
					</button>
					<button
						aria-label={`Remove ${column.displayName} filter`}
						className="ml-0.5 shrink-0 rounded-sm p-0.5 text-muted-foreground hover:text-foreground"
						onClick={handleRemove}
						type="button"
					>
						<IconX className="size-3" />
					</button>
				</span>
			</PopoverTrigger>
			<PopoverContent align="start" className="w-64 p-2">
				<div className="flex flex-col gap-2">
					<div className="font-medium text-muted-foreground text-xs">
						{column.displayName}
					</div>
					<OperatorSelector
						column={column}
						onSearchChange={() => {}}
						onSelect={handleOperatorChange}
						search=""
					/>
					<ValueInput
						column={column}
						onChange={(value) => onUpdate(condition.id, { value })}
						onCommit={() => setEditOpen(false)}
						operator={condition.operator}
						value={condition.value}
					/>
				</div>
			</PopoverContent>
		</Popover>
	);
}

import type {
	ColumnConfig,
	FilterCondition,
	FilterGroup,
} from "@adistack/data-explorer";
import { groupConditions, isFilterGroup } from "@adistack/data-explorer";
import { useMemo } from "react";

import { FilterChip } from "./filter-chip.tsx";
import { FilterCombinatorToggle } from "./filter-combinator-toggle.tsx";

interface FilterChipGroupProps {
	columnsConfig: ColumnConfig[];
	conditions: FilterCondition[];
	focusedChipIndex: number | null;
	handleCombinatorChange: (id: string, combinator: "and" | "or") => void;
	removeCondition: (id: string) => void;
	setFocusedChipIndex: (index: number | null) => void;
	updateCondition: (id: string, updates: Partial<FilterCondition>) => void;
}

type SharedChipProps = Pick<
	FilterChipGroupProps,
	| "columnsConfig"
	| "focusedChipIndex"
	| "handleCombinatorChange"
	| "removeCondition"
	| "setFocusedChipIndex"
	| "updateCondition"
>;

export function FilterChipGroup({
	conditions,
	columnsConfig,
	removeCondition,
	updateCondition,
	focusedChipIndex,
	setFocusedChipIndex,
	handleCombinatorChange,
}: FilterChipGroupProps): React.JSX.Element | null {
	const group = useMemo(() => groupConditions(conditions), [conditions]);
	const indexById = useMemo(
		() => new Map(conditions.map((c, i) => [c.id, i] as const)),
		[conditions],
	);
	const colById = useMemo(
		() => new Map(columnsConfig.map((c) => [c.id, c] as const)),
		[columnsConfig],
	);

	if (conditions.length === 0) return null;

	const shared: SharedChipProps = {
		columnsConfig,
		focusedChipIndex,
		handleCombinatorChange,
		removeCondition,
		setFocusedChipIndex,
		updateCondition,
	};

	const isFlat = group.conditions.length <= 1 || group.combinator === "and";
	if (isFlat) {
		return (
			<>
				{conditions.map((cond, i) => (
					<ChipWithCombinator
						chipIndex={i}
						colById={colById}
						condition={cond}
						key={cond.id}
						showCombinator={i > 0}
						{...shared}
					/>
				))}
			</>
		);
	}

	return (
		<>
			{group.conditions.map((item, g) => {
				if (isFilterGroup(item)) {
					return (
						<AndBracket
							colById={colById}
							group={item}
							indexById={indexById}
							key={item.id}
							showOrSeparator={g > 0}
							{...shared}
						/>
					);
				}

				return (
					<span key={item.id}>
						{g > 0 && <OrSeparator />}
						<ChipWithCombinator
							chipIndex={indexById.get(item.id) ?? -1}
							colById={colById}
							condition={item}
							showCombinator={false}
							{...shared}
						/>
					</span>
				);
			})}
		</>
	);
}

function OrSeparator(): React.JSX.Element {
	return (
		<span className="px-1 font-medium text-[10px] text-orange-600 uppercase">
			or
		</span>
	);
}

function AndBracket({
	group,
	indexById,
	colById,
	showOrSeparator,
	...shared
}: SharedChipProps & {
	colById: Map<string, ColumnConfig>;
	group: FilterGroup;
	indexById: Map<string, number>;
	showOrSeparator: boolean;
}): React.JSX.Element {
	return (
		<span>
			{!!showOrSeparator && <OrSeparator />}
			<span className="text-muted-foreground text-xs">(</span>
			{group.conditions.map((child, i) => {
				if (isFilterGroup(child)) {
					return (
						<AndBracket
							colById={colById}
							group={child}
							indexById={indexById}
							key={child.id}
							showOrSeparator={false}
							{...shared}
						/>
					);
				}
				return (
					<ChipWithCombinator
						chipIndex={indexById.get(child.id) ?? -1}
						colById={colById}
						condition={child}
						key={child.id}
						showCombinator={i > 0}
						{...shared}
					/>
				);
			})}
			<span className="text-muted-foreground text-xs">)</span>
		</span>
	);
}

function ChipWithCombinator({
	chipIndex,
	condition,
	showCombinator,
	colById,
	focusedChipIndex,
	handleCombinatorChange,
	removeCondition,
	setFocusedChipIndex,
	updateCondition,
}: SharedChipProps & {
	chipIndex: number;
	colById: Map<string, ColumnConfig>;
	condition: FilterCondition;
	showCombinator: boolean;
}): React.JSX.Element | null {
	const col = colById.get(condition.columnId);
	if (!col) return null;

	return (
		<>
			{!!showCombinator && (
				<FilterCombinatorToggle
					combinator={condition.combinator}
					onChange={(c) => handleCombinatorChange(condition.id, c)}
				/>
			)}
			<FilterChip
				column={col}
				condition={condition}
				onRemove={removeCondition}
				onSelect={() => setFocusedChipIndex(chipIndex)}
				onUpdate={updateCondition}
				selected={focusedChipIndex === chipIndex}
			/>
		</>
	);
}

import { cn } from "@/lib/utils";

interface FilterCombinatorToggleProps {
	combinator: "and" | "or";
	onChange: (combinator: "and" | "or") => void;
}

export function FilterCombinatorToggle({
	combinator,
	onChange,
}: FilterCombinatorToggleProps): React.JSX.Element {
	return (
		<button
			className={cn(
				"inline-flex h-5 items-center rounded px-1 font-medium text-[10px] text-muted-foreground uppercase tracking-wide transition-colors hover:bg-muted hover:text-foreground",
				combinator === "or" && "text-orange-600 hover:text-orange-700",
			)}
			onClick={() => onChange(combinator === "and" ? "or" : "and")}
			type="button"
		>
			{combinator}
		</button>
	);
}

import type { FilterCondition } from "@adistack/data-explorer";
import { useCallback, useEffect, useRef, useState } from "react";

interface FilterBarKeyboardOptions {
	conditions: FilterCondition[];
	inputValue: string;
	onRemove: (id: string) => void;
	onResetFlow: () => void;
	popoverOpen: boolean;
}

interface FilterBarKeyboard {
	containerRef: React.RefObject<HTMLDivElement | null>;
	focusedChipIndex: number | null;
	focusInput: () => void;
	handleInputKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void;
	inputRef: React.RefObject<HTMLInputElement | null>;
	setFocusedChipIndex: (index: number | null) => void;
}

function focusChip(
	container: HTMLDivElement | null,
	id: string | undefined,
	action: "click" | "focus",
): void {
	if (!(container && id)) return;
	const chipEl = container.querySelector(
		`[data-filter-chip="${id}"] button:first-child`,
	);
	if (chipEl instanceof HTMLElement) {
		if (action === "click") chipEl.click();
		else chipEl.focus();
	}
}

export function useFilterBarKeyboard(
	opts: FilterBarKeyboardOptions,
): FilterBarKeyboard {
	const { conditions, inputValue, onRemove, popoverOpen, onResetFlow } = opts;
	const containerRef = useRef<HTMLDivElement>(null);
	const inputRef = useRef<HTMLInputElement>(null);
	const [focusedChipIndex, setFocusedChipIndex] = useState<number | null>(null);

	const focusInput = useCallback(() => {
		inputRef.current?.focus();
	}, []);

	const handleInputKeyDown = useCallback(
		(e: React.KeyboardEvent<HTMLInputElement>) => {
			if (e.key === "ArrowLeft") {
				const target = e.currentTarget;
				if (
					target.selectionStart === 0 &&
					target.selectionEnd === 0 &&
					conditions.length > 0
				) {
					e.preventDefault();
					const newIdx =
						focusedChipIndex === null
							? conditions.length - 1
							: Math.max(0, focusedChipIndex - 1);
					setFocusedChipIndex(newIdx);
					return;
				}
			}

			if (e.key === "ArrowRight" && focusedChipIndex !== null) {
				e.preventDefault();
				if (focusedChipIndex < conditions.length - 1) {
					setFocusedChipIndex(focusedChipIndex + 1);
				} else {
					setFocusedChipIndex(null);
					focusInput();
				}
				return;
			}

			if (
				(e.key === "Backspace" || e.key === "Delete") &&
				focusedChipIndex !== null
			) {
				e.preventDefault();
				const cond = conditions[focusedChipIndex];
				if (cond) {
					onRemove(cond.id);
					if (conditions.length <= 1) {
						setFocusedChipIndex(null);
						focusInput();
					} else if (focusedChipIndex >= conditions.length - 1) {
						setFocusedChipIndex(conditions.length - 2);
					}
				}
				return;
			}

			if (
				e.key === "Backspace" &&
				inputValue === "" &&
				conditions.length > 0 &&
				focusedChipIndex === null
			) {
				e.preventDefault();
				setFocusedChipIndex(conditions.length - 1);
				return;
			}

			if (e.key === "Enter" && focusedChipIndex !== null) {
				e.preventDefault();
				focusChip(
					containerRef.current,
					conditions[focusedChipIndex]?.id,
					"click",
				);
				return;
			}

			if (e.key === "Escape") {
				if (popoverOpen) {
					onResetFlow();
					focusInput();
					return;
				}
				setFocusedChipIndex(null);
				return;
			}

			if (focusedChipIndex !== null && e.key.length === 1) {
				setFocusedChipIndex(null);
			}
		},
		[
			conditions,
			onRemove,
			focusedChipIndex,
			inputValue,
			popoverOpen,
			onResetFlow,
			focusInput,
		],
	);

	useEffect(() => {
		const handleKeyDown = (e: KeyboardEvent) => {
			if ((e.ctrlKey || e.metaKey) && e.key === "f") {
				e.preventDefault();
				inputRef.current?.focus();
				setFocusedChipIndex(null);
			}
		};

		window.addEventListener("keydown", handleKeyDown);
		return () => window.removeEventListener("keydown", handleKeyDown);
	}, []);

	const focusedId =
		focusedChipIndex !== null ? conditions[focusedChipIndex]?.id : undefined;

	useEffect(() => {
		if (focusedChipIndex !== null) {
			focusChip(containerRef.current, focusedId, "focus");
		}
	}, [focusedChipIndex, focusedId]);

	return {
		containerRef,
		focusedChipIndex,
		focusInput,
		handleInputKeyDown,
		inputRef,
		setFocusedChipIndex,
	};
}

export function parseDateValue(v: unknown): Date | null {
	if (v instanceof Date) return Number.isNaN(v.getTime()) ? null : v;
	if (typeof v === "string" || typeof v === "number") {
		if (v === "") return null;
		const d = new Date(v);
		return Number.isNaN(d.getTime()) ? null : d;
	}
	return null;
}

export function toValidDate(value: string | undefined): Date | undefined {
	return parseDateValue(value) ?? undefined;
}
